test('dois contadores são independentes', () => {
  const contadorA = criarContador();
  const contadorB = criarContador();
  contadorA();
  contadorA();
  assert.equal(contadorA(), 3);
  assert.equal(contadorB(), 1);
});

test('cada chamada de criarContador recomeça a contagem', () => {
  const primeiro = criarContador();
  primeiro();
  const segundo = criarContador();
  assert.equal(segundo(), 1);
  assert.equal(primeiro(), 2);
});

solutionCode:
export function criarContador() {
  let valor = 0;
  return function () {
    valor += 1;
    return valor;
  };
}
